import {fieldsFromScreenshot,screenshotEnvelope,preserveScreenshotOutside,screenshotRegions,screenshotWordsToRecords,validateScreenshotGrid,SCREENSHOT_LIMITS} from '../core/screenshot.js';
import {weekAt,parseWeeks} from '../core/model.js';

const VENDOR=new URL('../vendor/ocr/',import.meta.url),E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let scriptPromise;
async function engine(){
 if(globalThis.Tesseract)return globalThis.Tesseract;
 if(!scriptPromise)scriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL('tesseract.min.js',VENDOR);script.onload=()=>globalThis.Tesseract?resolve(globalThis.Tesseract):reject(Error('本机OCR引擎没有正确加载'));script.onerror=()=>reject(Error('截图识别资源无法读取，请使用完整安装包或重新加载网页'));document.head.append(script);}).catch(e=>{scriptPromise=null;throw e;});
 return scriptPromise;
}
function wordsOf(data){return (data.blocks||[]).flatMap(block=>(block.paragraphs||[]).flatMap(p=>(p.lines||[]).flatMap(line=>line.words||[])));}
export function setupScreenshotImport({getSettings,getCourses=()=>[],notify=()=>{},openSheet,onPreview}){
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./screenshot-import.css',import.meta.url);document.head.append(css);
 const dialog=document.createElement('dialog');dialog.id='screenshot-sheet';dialog.className='sheet screenshot-sheet';
 dialog.innerHTML='<div class="sheet-handle"></div><div class="sheet-title"><div><small>本机识别 · 先核对再导入</small><h2>截图导入课表</h2></div><button type="button" id="screenshot-close" class="plain-icon" aria-label="关闭截图导入">✕</button></div><p class="sheet-tip">选择完整课表截图，框住课程区，排除星期标题和左侧时间。识别结果可逐条修改，不会自动覆盖课表。</p><input id="screenshot-file" type="file" accept="image/png,image/jpeg,image/webp" hidden><div class="package-actions"><button type="button" id="screenshot-choose">选择截图</button><button type="button" id="screenshot-corners" disabled>点图框选课程区</button></div><div class="screenshot-preview" hidden><canvas id="screenshot-canvas" aria-label="截图与星期节次校准预览"></canvas></div><div class="screenshot-grid-controls"><label>星期列数<select id="screenshot-days"><option value="7">周一至周日 · 7列</option><option value="5">周一至周五 · 5列</option></select></label><label>本次更新周次<input id="screenshot-weeks" placeholder="例如 6 或 1-16" inputmode="numeric"></label><label>截图第一节<input id="screenshot-first" type="number" min="1" max="12" value="1"></label><label>截图最后一节<input id="screenshot-last" type="number" min="1" max="12" value="12"></label><label>左边界 %<input id="screenshot-left" type="number" min="0" max="100" step=".5" value="10"></label><label>右边界 %<input id="screenshot-right" type="number" min="0" max="100" step=".5" value="99"></label><label>上边界 %<input id="screenshot-top" type="number" min="0" max="100" step=".5" value="25"></label><label>下边界 %<input id="screenshot-bottom" type="number" min="0" max="100" step=".5" value="96"></label></div><p class="sheet-tip">周课表截图默认只更新所填周次，保留其他周。若截图包含整学期周次，请修改上方范围并逐条核对。</p><div class="package-actions"><button type="button" id="screenshot-recognize" disabled>开始本机识别</button><button type="button" id="screenshot-stop" hidden>停止识别</button></div><p id="screenshot-status" class="sheet-tip" role="status" aria-live="polite"></p><progress id="screenshot-progress" max="1" value="0" hidden></progress><div id="screenshot-records"></div><button type="button" id="screenshot-add" class="action-row">＋ 手动添加一条</button><label class="screenshot-review"><input id="screenshot-reviewed" type="checkbox">我已核对课程、教室、星期、节次和周次</label><button type="button" id="screenshot-preview-import" class="primary-button">核对完成，预览导入</button><p id="screenshot-error" class="occurrence-error" role="alert"></p>';
 document.body.append(dialog);const $=s=>dialog.querySelector(s);let image=null,imageURL=null,worker=null,generation=0,busy=false,records=[],corners=null;
 const button=document.createElement('button');button.type='button';button.className='action-row';button.dataset.action='screenshot';button.innerHTML='<span aria-hidden="true">▧</span><span>截图导入课表<small>离线识别 · 核对后更新</small></span><span aria-hidden="true">›</span>';
 const menu=document.getElementById('menu-sheet');if(menu)menu.insertBefore(button,menu.querySelector('[data-action="import"]')||null);
 function settings(){return getSettings();}
 function scope(){const weeks=parseWeeks($('#screenshot-weeks').value);if(weeks.some(w=>w>settings().totalWeeks))throw Error('周次超出本学期范围');return weeks;}
 function grid(){return validateScreenshotGrid(Object.fromEntries(['left','right','top','bottom','days','first','last'].map(k=>[k,$('#screenshot-'+k).value])));}
 function status(text){$('#screenshot-status').textContent=text;}
 function error(e){$('#screenshot-error').textContent=e.name==='EncodingError'?'这张图片无法读取，请重新截屏后选择':e.message||String(e);}
 function setBusy(value){busy=value;$('#screenshot-recognize').disabled=value||!image;$('#screenshot-choose').disabled=value;$('#screenshot-corners').disabled=value||!image;$('#screenshot-stop').hidden=!value;$('#screenshot-progress').hidden=!value;for(const input of dialog.querySelectorAll('.screenshot-grid-controls input,.screenshot-grid-controls select'))input.disabled=value;}
 function stop(){generation++;const previous=worker;worker=null;if(previous)previous.terminate().catch(()=>{});setBusy(false);}
 function open(){if(!$('#screenshot-weeks').value)$('#screenshot-weeks').value=String(Math.max(1,Math.min(settings().totalWeeks,weekAt(settings().startDate))));$('#screenshot-error').textContent='';openSheet('#screenshot-sheet');}
 document.addEventListener('click',e=>{if(e.target.closest('[data-action="screenshot"]'))open();});
 $('#screenshot-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(busy){stop();status('识别已停止，原课表未改动。');}corners=null;});
 $('#screenshot-choose').onclick=()=>$('#screenshot-file').click();
 $('#screenshot-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;$('#screenshot-error').textContent='';try{if(file.size>SCREENSHOT_LIMITS.bytes)throw Error('截图超过20MB，请裁去无关区域后再选择');if(!['image/png','image/jpeg','image/webp'].includes(file.type)&&! /\.(png|jpe?g|webp)$/i.test(file.name))throw Error('请选择PNG、JPEG或WebP截图');const nextURL=URL.createObjectURL(file),next=new Image();try{next.src=nextURL;await next.decode();if(!next.naturalWidth||next.naturalWidth*next.naturalHeight>SCREENSHOT_LIMITS.pixels)throw Error('截图像素过大，请裁剪或缩小到2400万像素以内');}catch(cause){URL.revokeObjectURL(nextURL);throw cause;}if(imageURL)URL.revokeObjectURL(imageURL);imageURL=nextURL;image=next;records=[];renderRecords();$('#screenshot-reviewed').checked=false;$('.screenshot-preview').hidden=false;setBusy(false);draw();status('已在本机读取截图。请先校准绿色网格，再开始识别。');}catch(cause){error(cause);}};
 function draw(){if(!image)return;const canvas=$('#screenshot-canvas'),scale=Math.min(1,1500/image.naturalWidth);canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);let g;try{g=grid();}catch{return;}const x=canvas.width*g.left/100,y=canvas.height*g.top/100,w=canvas.width*(g.right-g.left)/100,h=canvas.height*(g.bottom-g.top)/100;ctx.fillStyle='#071d3d66';ctx.fillRect(0,0,canvas.width,y);ctx.fillRect(0,y,x,h);ctx.fillRect(x+w,y,canvas.width-x-w,h);ctx.fillRect(0,y+h,canvas.width,canvas.height-y-h);ctx.strokeStyle='#00b894';ctx.lineWidth=Math.max(2,canvas.width/350);for(let i=0;i<=g.days;i++){ctx.beginPath();ctx.moveTo(x+w*i/g.days,y);ctx.lineTo(x+w*i/g.days,y+h);ctx.stroke();}for(let i=0;i<=g.last-g.first+1;i++){ctx.beginPath();ctx.moveTo(x,y+h*i/(g.last-g.first+1));ctx.lineTo(x+w,y+h*i/(g.last-g.first+1));ctx.stroke();}ctx.font='bold '+Math.max(14,canvas.width/45)+'px sans-serif';ctx.fillStyle='#00856c';ctx.textBaseline='top';for(let day=1;day<=g.days;day++){ctx.fillText('周'+['一','二','三','四','五','六','日'][day-1],x+(day-1)*w/g.days+3,y+3);}}
 for(const input of dialog.querySelectorAll('.screenshot-grid-controls input,.screenshot-grid-controls select'))input.onchange=()=>{draw();$('#screenshot-reviewed').checked=false;};
 $('#screenshot-corners').onclick=()=>{corners=[];status('先点课程区左上角，再点右下角；不要包括星期标题和左侧时间。');};
 $('#screenshot-canvas').onclick=e=>{if(!corners||busy)return;const r=e.target.getBoundingClientRect(),point={x:Math.round((e.clientX-r.left)/r.width*1000)/10,y:Math.round((e.clientY-r.top)/r.height*1000)/10};corners.push(point);if(corners.length===1){status('左上角已选，请再点课程区右下角。');return;}const [a,b]=corners;corners=null;$('#screenshot-left').value=Math.min(a.x,b.x);$('#screenshot-right').value=Math.max(a.x,b.x);$('#screenshot-top').value=Math.min(a.y,b.y);$('#screenshot-bottom').value=Math.max(a.y,b.y);draw();status('课程区已框选，请核对星期列数、截图首末节次和周次。');};
 function readRecords(){for(const row of $('#screenshot-records').querySelectorAll('[data-screenshot-row]')){const record=records[Number(row.dataset.screenshotRow)];for(const field of row.querySelectorAll('[name]'))record[field.name]=field.value;}}
 function renderRecords(){
  $('#screenshot-records').innerHTML=records.map((c,i)=>`<fieldset class="screenshot-record" data-screenshot-row="${i}"><legend>第 ${i+1} 条 · 待核对</legend><label>课程名称<input name="name" maxlength="100" value="${E(c.name)}"></label><div class="screenshot-record-grid"><label>星期<select name="day">${[1,2,3,4,5,6,7].map(day=>`<option value="${day}" ${Number(c.day)===day?'selected':''}>周${['一','二','三','四','五','六','日'][day-1]}</option>`).join('')}</select></label><label>起始节<input name="start" type="number" min="1" max="12" value="${E(c.start)}"></label><label>结束节<input name="end" type="number" min="1" max="12" value="${E(c.end)}"></label><label>周次<input name="weeks" value="${E(Array.isArray(c.weeks)?c.weeks.join(','):c.weeks)}"></label></div><label>教室<input name="location" maxlength="160" value="${E(c.location)}"></label><label>教师（可留空）<input name="teacher" maxlength="100" value="${E(c.teacher)}"></label>${c.ocrText?`<details><summary>识别原文</summary><pre>${E(c.ocrText)}</pre></details>`:''}<button type="button" data-screenshot-remove="${i}">删除这条</button></fieldset>`).join('');
 }
 $('#screenshot-records').addEventListener('input',()=>$('#screenshot-reviewed').checked=false);
 $('#screenshot-records').addEventListener('click',e=>{const remove=e.target.closest('[data-screenshot-remove]');if(!remove)return;readRecords();records.splice(Number(remove.dataset.screenshotRemove),1);renderRecords();$('#screenshot-reviewed').checked=false;});
 $('#screenshot-add').onclick=()=>{if(busy)return;try{readRecords();if(records.length>=SCREENSHOT_LIMITS.records)throw Error('最多添加150条');records.push({name:'',day:1,start:1,end:2,weeks:scope(),location:'',teacher:''});renderRecords();$('#screenshot-reviewed').checked=false;$('#screenshot-records .screenshot-record:last-child input').focus();}catch(cause){error(cause);}};
 function crop(rectangle){const target=document.createElement('canvas'),scale=Math.min(4,Math.max(1,650/rectangle.width));target.width=Math.round(rectangle.width*scale);target.height=Math.round(rectangle.height*scale);target.getContext('2d').drawImage(image,rectangle.left,rectangle.top,rectangle.width,rectangle.height,0,0,target.width,target.height);return {canvas:target,scale};}
 $('#screenshot-recognize').onclick=async()=>{
  if(busy||!image)return;$('#screenshot-error').textContent='';let token;
  try{const g=grid(),weeks=scope(),source=document.createElement('canvas');source.width=image.naturalWidth;source.height=image.naturalHeight;source.getContext('2d').drawImage(image,0,0);const pixels=source.getContext('2d',{willReadFrequently:true}).getImageData(0,0,source.width,source.height),layout=screenshotRegions(pixels.data,source.width,source.height,g);setBusy(true);token=++generation;$('#screenshot-reviewed').checked=false;status('正在加载本机中文识别引擎，截图不会上传。');const T=await engine();if(token!==generation)return;
   const created=await T.createWorker(['chi_sim','eng'],1,{workerPath:new URL('worker.min.js',VENDOR).href,corePath:VENDOR.href,langPath:VENDOR.href.replace(/\/$/,''),workerBlobURL:false,gzip:false,cacheMethod:'none',logger:m=>{if(token===generation&&m.status==='recognizing text')$('#screenshot-progress').value=m.progress;}});if(token!==generation){await created.terminate();return;}worker=created;
   const drafts=[];const jobs=layout.regions.length?layout.regions:Array.from({length:g.days},(_,i)=>({day:i+1,left:layout.rectangle.left+i*layout.columnWidth,top:layout.rectangle.top,width:layout.columnWidth,height:layout.rectangle.height,fallback:true}));
   for(let i=0;i<jobs.length;i++){
    if(token!==generation)return;const job=jobs[i],sample=crop(job);status(`正在本机识别 ${i+1}/${jobs.length}，完成后请逐条核对。`);await worker.setParameters({tessedit_pageseg_mode:job.fallback?'11':'6',preserve_interword_spaces:'1',user_defined_dpi:'300'});
    let timeout;const result=await Promise.race([worker.recognize(sample.canvas,{}, {text:true,blocks:true}),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error('识别耗时过长，可停止后缩小截图再试')),120000);})]).finally(()=>clearTimeout(timeout));if(token!==generation)return;
    if(job.fallback){const words=wordsOf(result.data).map(word=>({...word,bbox:Object.fromEntries(Object.entries(word.bbox).map(([k,v])=>[k,v/sample.scale]))}));drafts.push(...screenshotWordsToRecords(words,job.day,{first:g.first,last:g.last,height:job.height},weeks));}
    else {const fields=fieldsFromScreenshot(result.data.text);if(fields.name)drafts.push({...fields,day:job.day,start:job.start,end:job.end,weeks:fields.weeks||weeks,ocrText:result.data.text});}
   }
   records=drafts.slice(0,SCREENSHOT_LIMITS.records);renderRecords();status(records.length?`识别出 ${records.length} 条草稿。${layout.regions.length?'已按颜色课块估计节次。':'未找到稳定的颜色课块，暂按单节列出，请合并连堂节次。'}请逐条核对后预览导入。`:'没有识别到课程。可调整课程区后重试，或手动添加；原课表未改动。');
  }catch(cause){if(token===generation||token===undefined){status('识别未完成，原课表未改动。');error(cause);}}
  finally{if(token===generation){const previous=worker;worker=null;if(previous)await previous.terminate().catch(()=>{});setBusy(false);}}
 };
 $('#screenshot-stop').onclick=()=>{stop();status('识别已停止，原课表未改动。');};
 $('#screenshot-preview-import').onclick=()=>{if(busy)return;$('#screenshot-error').textContent='';try{if(!$('#screenshot-reviewed').checked)throw Error('请逐条核对后勾选确认');readRecords();const g=grid();if(records.some(c=>Number(c.day)>g.days||Number(c.start)<g.first||Number(c.end)>g.last))throw Error('课程节次或星期超出本次截图窗口，请先调整网格范围');const value=preserveScreenshotOutside(getCourses(),screenshotEnvelope(records,settings(),scope()),g);onPreview(value);dialog.close();}catch(cause){error(cause);}};
 return {open,close:()=>dialog.close(),destroy(){stop();if(imageURL)URL.revokeObjectURL(imageURL);dialog.remove();button.remove();css.remove();}};
}
